    /// <summary>The profile of a preset; circle when unknown or absent.</summary>
    public static double[] Get(string? preset) => Profiles.TryGetValue(preset ?? "circle", out var p) ? p : Profiles["circle"];

    /// <summary>The profile's rise at <paramref name="t"/> (0 … 1 across the bevel width), linearly interpolated.</summary>
    public static double At(double[] profile, double t)
    {
        var x = Math.Clamp(t, 0, 1) * (profile.Length - 1);
        var i = Math.Min((int)x, profile.Length - 2);
        return profile[i] + (profile[i + 1] - profile[i]) * (x - i);
    }
}
